import cn from 'classnames';
import { ISplideCarouselProps, ICarouselDownloadSlide, IListLayoutProps } from './splide-carousel.types';
import { ICarouselDefaultSlide, ICarouselTeaserSlide } from '../carousel/carousel.types';
import { Teaser } from '../teaser/teaser';
import './splide-carousel.scss';

function SimpleImage({ id, src, alt, uuid, srcSet, className, useCaption, title }: ICarouselDefaultSlide) {
  const itemId = id?.split('-')[1];
  return (
    <div id={`image-${itemId}`} className={cn('image', className)}>
      <div
        data-asset-id={uuid}
        data-cmp-data-layer=""
        className="cmp-image"
        itemScope
        itemType="http://schema.org/ImageObject"
      >
        <img
          srcSet={srcSet}
          src={src}
          loading="lazy"
          className="cmp-image__image"
          itemProp="contentUrl"
          width="850"
          height="509"
          alt={alt}
        />
      </div>
      {useCaption && title && (
        <span className="cmp-image__title" itemProp="caption">
          {title}
        </span>
      )}
    </div>
  );
}

function Download({
  id,
  url,
  title,
  description,
  filename,
  size,
  format,
  actionText,
  image,
  className,
  layoutAlignContent,
}: ICarouselDownloadSlide) {
  const iconAligned = cn({
    'download--icon-left': layoutAlignContent === 'left',
    'download--icon-right': layoutAlignContent === 'right',
  });

  return (
    <div className={cn('download', { 'download--with-image': image }, iconAligned, className)}>
      <div id={id} className="cmp-download">
        {image && (
          <div id={`image-${image.id}`} data-asset-id={image.uuid} className="cmp-image">
            <img
              loading="lazy"
              className="cmp-image__image"
              itemProp="contentUrl"
              src={image.src}
              alt={image.alt}
              srcSet={image.srcset}
              title={title}
            />
            <meta itemProp="caption" content={image.alt} />
          </div>
        )}
        <h3 className="cmp-download__title">
          <a className="cmp-download__title-link" href={url} download>
            {title}
          </a>
        </h3>
        {description && <div className="cmp-download__description" dangerouslySetInnerHTML={{ __html: description }} />}
        <dl className="cmp-download__properties">
          <div className="cmp-download__property cmp-download__property--filename">
            <dt className="cmp-download__property-label">Filename</dt>
            <dd className="cmp-download__property-content">{filename}</dd>
          </div>
          <div className="cmp-download__property cmp-download__property--size">
            <dt className="cmp-download__property-label">Size</dt>
            <dd className="cmp-download__property-content">{size}</dd>
          </div>
          <div className="cmp-download__property cmp-download__property--format">
            <dt className="cmp-download__property-label">Format</dt>
            <dd className="cmp-download__property-content">{format}</dd>
          </div>
        </dl>
        <a className="cmp-download__action" href={url} download>
          <span className="cmp-download__action-text">{actionText}</span>
        </a>
      </div>
    </div>
  );
}

function ListLayout({ children, className }: IListLayoutProps) {
  return (
    <div className={cn('list', className)}>
      <ul className="cmp-list">{children}</ul>
    </div>
  );
}

export function SplideCarousel({
  className,
  classNameSlide,
  typeCarousel,
  structureType = 'default',
  ':itemsOrder': itemsOrder,
  ':items': items,
  useExpand = false,
}: ISplideCarouselProps<ICarouselDefaultSlide | ICarouselTeaserSlide | ICarouselDownloadSlide>) {
  const cnModifications = cn({
    'ds-brand-expand': useExpand,
  });

  function ComponentByType(index: number, itemOrder: string) {
    const classNameSlideComponent = structureType === 'default' ? classNameSlide : null;

    return (
      <>
        {typeCarousel === 'image' ? (
          <SimpleImage key={index} id={items[itemOrder].id} {...items[itemOrder]} className={classNameSlideComponent} />
        ) : null}
        {typeCarousel === 'teaser' ? (
          <Teaser
            key={index}
            {...items[itemOrder]}
            id={items[itemOrder].id}
            className={classNameSlideComponent}
            {...items[itemOrder]}
          />
        ) : null}
        {typeCarousel === 'download' ? (
          <Download key={index} {...items[itemOrder]} id={items[itemOrder].id} className={classNameSlideComponent} />
        ) : null}
      </>
    );
  }

  return (
    <div
      className={cn(
        'ds-splide-carousel container responsivegrid aem-GridColumn aem-GridColumn--default--12',
        cnModifications,
        className,
      )}
    >
      <div className="cmp-container">
        {structureType === 'list' ? (
          <ListLayout className={classNameSlide}>
            {itemsOrder.length &&
              itemsOrder.map((itemOrder, index) => (
                <li key={items[itemOrder].id} className="cmp-list__item">
                  {ComponentByType(index, itemOrder)}
                </li>
              ))}
          </ListLayout>
        ) : (
          <div className="aem-Grid aem-Grid--12 aem-Grid--default--12">
            {itemsOrder.length &&
              itemsOrder.map((itemOrder, index) => (
                <>{ComponentByType(index, itemOrder)}</>
              ))}
          </div>
        )}
      </div>
    </div>
  );
}

export default SplideCarousel;
